'use client'

import Link from 'next/link'
import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase/client'
import { getUserRole } from '@/lib/supabase/roles'
import { type ListingActivityRecord, type ProductApprovalState, type VendorProduct, vendorCatalogService } from '@/lib/vendor/catalog'
import { AdminComments } from '../../components/AdminComments'
import { ApprovalTimeline } from '../../components/ApprovalTimeline'
import { CatalogFeedback } from '../../components/CatalogFeedback'
import { ChangeHistory } from '../../components/ChangeHistory'
import { LifecycleActions } from '../../components/LifecycleActions'
import { ListingActivityHistory } from '../../components/ListingActivityHistory'
import { ListingLifecycleBadge } from '../../components/ListingLifecycleBadge'
import { ProductStatusBadge } from '../../components/ProductStatusBadge'
import { RejectionReason } from '../../components/RejectionReason'
import { ResubmitAction } from '../../components/ResubmitAction'

export default function ProductDetailsPage({ params }: { params: Promise<{ id: string }> }) {
  const [product, setProduct] = useState<VendorProduct | null>(null); const [approval, setApproval] = useState<ProductApprovalState | null>(null); const [activity, setActivity] = useState<ListingActivityRecord[]>([]); const [loading, setLoading] = useState(true); const [missing, setMissing] = useState(false); const [error, setError] = useState('')
  useEffect(() => { let mounted = true; void Promise.all([params, createClient().auth.getUser()]).then(async ([route, { data: { user } }]) => { if (!user || (getUserRole(user) !== 'vendor' && getUserRole(user) !== 'admin')) return; const current = await vendorCatalogService.get(user.id, route.id); if (mounted) { setProduct(current); setMissing(!current); if (current) { setApproval(await vendorCatalogService.getApprovalState(user.id, current.id)); setActivity(await vendorCatalogService.getListingActivity(user.id, current.id)) }; setLoading(false) } }); return () => { mounted = false } }, [params])
  async function handleLifecycleAction(action: Parameters<typeof vendorCatalogService.performLifecycleAction>[2]) { if (!product) return; try { const user = (await createClient().auth.getUser()).data.user; if (!user) return; setProduct(await vendorCatalogService.performLifecycleAction(user.id, product.id, action)); setActivity(await vendorCatalogService.getListingActivity(user.id, product.id)) } catch { setError('This lifecycle action could not be completed.') } }
  if (loading) return <main className="vendor-page"><div className="catalog-page-shell"><CatalogFeedback type="loading">Loading product lifecycle details...</CatalogFeedback></div></main>
  if (missing || !product || !approval) return <main className="vendor-page"><div className="catalog-page-shell"><CatalogFeedback type="error">This product could not be found.</CatalogFeedback><Link href="/vendor/products" className="btn-skip">Back to catalog</Link></div></main>
  return <main className="vendor-page"><header className="vendor-header"><Link href="/vendor/products" className="logo logo-active">Furnish<span>AI</span></Link><nav><Link href="/vendor/products" className="btn-skip">Catalog</Link><Link href={`/vendor/products/${product.id}/edit`} className="btn-next">Edit product</Link></nav></header><div className="product-detail-shell"><div className="product-detail-heading"><div><p className="vendor-eyebrow">Catalog / Listing lifecycle</p><h1>{product.name}</h1><p>{product.sku} · {product.category}</p></div><div className="approval-heading-actions"><ProductStatusBadge status={product.status} /><ListingLifecycleBadge status={product.lifecycleStatus} /><ResubmitAction productId={product.id} status={product.status} /></div></div>{error ? <CatalogFeedback type="error">{error}</CatalogFeedback> : null}<LifecycleActions product={product} onAction={handleLifecycleAction} /><RejectionReason reason={product.rejectionReason} requestedChanges={approval.requestedChanges} /><div className="approval-overview-grid"><section className="product-detail-card"><h2>Approval timeline</h2><ApprovalTimeline history={approval.history} /></section><section className="product-detail-card"><h2>Reviewer comments</h2><AdminComments comments={approval.adminComments} /></section></div><ChangeHistory history={approval.history} /><ListingActivityHistory records={activity} /><div className="product-detail-grid"><section className="product-detail-card"><h2>Listing information</h2><dl><div><dt>Price</dt><dd>₹{product.price.toLocaleString('en-IN')}</dd></div><div><dt>Stock</dt><dd>{product.stock} units</dd></div><div><dt>Listing state</dt><dd>{product.lifecycleStatus}</dd></div><div><dt>Last updated</dt><dd>{new Date(product.updatedAt).toLocaleString('en-IN')}</dd></div></dl><h3>Description</h3><p className="product-detail-description">{product.description}</p></section><section className="product-detail-card"><h2>Images and variants</h2><div className="product-image-grid">{product.images.length ? product.images.map((image) => <div className="product-image-tile" key={image.id}><img src={image.previewUrl} alt={image.altText} /></div>) : <p className="variant-empty">No images added.</p>}</div><h3 className="detail-section-title">Variants</h3>{product.variants.length ? <div className="detail-variants">{product.variants.map((variant) => <div key={variant.id}><strong>{variant.name}</strong><span>{variant.option} · {variant.sku} · ₹{variant.price.toLocaleString('en-IN')} · {variant.stock} in stock</span></div>)}</div> : <p className="variant-empty">No variants added.</p>}</section></div></div></main>
}